1	import {
2	    Flex,
3	} from '@mantine/core';
4	import type { Metadata } from 'next';
5	import { notFound, permanentRedirect } from 'next/navigation';
6	import { cache } from 'react';
7	import z from 'zod';
8	
9	import { setGameResult } from '@/actions/setGameResult';
10	import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
11	import { GameDaySummary } from '@/components/GameDaySummary/GameDaySummary';
12	import { GameResultForm } from '@/components/GameResultForm/GameResultForm';
13	import { getUserRole } from '@/lib/auth.server';
14	import { formatDate } from '@/lib/dates';
15	import { getGameWinnersFromTeams } from '@/lib/gameResult';
16	import gameDayService from '@/services/GameDay';
17	import outcomeService from '@/services/Outcome';
18	import { FootyChannel } from '@/types/FootyChannel';
19	
20	interface PageProps {
21	    params: Promise<{ id: string }>;
22	}
23	
24	/**
25	 * Unpacks and validates route parameters for the game detail page.
26	 *
27	 * Validates the `id` parameter as a positive integer, retrieves the
28	 * corresponding game day, and handles redirects to the canonical URL if needed.
29	 *
30	 * @param params - The route parameters object containing the `id` property
31	 * @returns A promise that resolves to an object containing the validated
32	 * `gameDay`
33	 * @throws Calls `notFound()` if the game day cannot be found or the ID is
34	 * invalid
35	 * @throws Calls `permanentRedirect()` if the current URL doesn't match the
36	 * canonical URL
37	 */
38	const unpackParams = cache(async (
39	    params: PageProps['params'],
40	) => {
41	    const { id } = await params;
42	
43	    const gameDayId = z.coerce.number().int().min(1).safeParse(id);
44	    const gameDay = gameDayId.success ? await gameDayService.get(gameDayId.data) : undefined;
45	    if (!gameDay) notFound();
46	
47	    const canonicalUrl = `/footy/game/${gameDay.id}`;
48	    const currentUrl = `/footy/game/${id}`;
49	    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
50	
51	    return { gameDay };
52	});
53	
54	/**
55	 * Generates metadata for a game page.
56	 * @param props - The page props containing route parameters
57	 * @param props.params - Route parameters including the game ID
58	 * @returns A promise that resolves to metadata with the game title and date
59	 */
60	export async function generateMetadata(props: PageProps): Promise<Metadata> {
61	    const { gameDay } = await unpackParams(props.params);
62	
63	    return {
64	        title: formatDate(gameDay.date),
65	    };
66	}
67	
68	/**
69	 * Displays a football game day page with game details, team information, and
70	 * navigation.
71	 *
72	 * This is an async Server Component that fetches game data, determines user
73	 * role, and renders game results, player teams, and administrative controls
74	 * based on permissions.
75	 *
76	 * @component
77	 * @param {PageProps} props - The page component props
78	 * @param {object} props.params - Route parameters containing the game ID
79	 * @returns {Promise<React.ReactElement>} A flex container with game navigation,
80	 * admin controls, and game summary
81	 *
82	 * @remarks
83	 * - Fetches previous and next game days for navigation
84	 * - Retrieves team rosters (up to 10 players per team) for the current game day
85	 * - Calculates game winners from team data
86	 * - Only displays the GameResultForm if the user has an 'admin' role
87	 * - Navigation links (Previous/Next) are conditionally rendered based on data
88	 *   availability
89	 *
90	 * @requires getUserRole - To determine user permissions
91	 * @requires unpackParams - To extract gameDay from route params
92	 * @requires gameDayService.getPrevious - To fetch previous game
93	 * @requires gameDayService.getNext - To fetch next game
94	 * @requires outcomeService.getTeamPlayersByGameDay - To fetch team rosters
95	 * @requires getGameWinnersFromTeams - To calculate match winners
96	 */
97	const GamePage = async (props: PageProps) => {
98	    const { gameDay } = await unpackParams(props.params);
99	    const [role, prevGameDay, nextGameDay, teamA, teamB] = await Promise.all([
100	        getUserRole(),
101	        gameDayService.getPrevious(gameDay.id),
102	        gameDayService.getNext(gameDay.id),
103	        outcomeService.getTeamPlayersByGameDay(gameDay.id, 'A', 10),
104	        outcomeService.getTeamPlayersByGameDay(gameDay.id, 'B', 10),
105	    ]);
106	    const winners = getGameWinnersFromTeams(teamA, teamB);
107	
108	    return (
109	        <Flex w="100%" direction="column" gap="md">
110	            <AutoRefresh channels={[FootyChannel.Games, FootyChannel.Results]} />
111	            <GameDaySummary
112	                gameDay={gameDay}
113	                prevGameDay={prevGameDay}
114	                nextGameDay={nextGameDay}
115	                teamA={teamA}
116	                teamB={teamB}
117	            />
118	            {role === 'admin' && !!gameDay.game && (
119	                <GameResultForm
120	                    gameDayId={gameDay.id}
121	                    bibs={gameDay.bibs ?? null}
122	                    winners={winners}
123	                    setGameResult={setGameResult}
124	                />
125	            )}
126	        </Flex>
127	    );
128	};
129	
130	export default GamePage;
