export const Render: Story = {
    args: {
        gameId: 1249,
        gameDate: '3rd February 2026',
        responses: defaultResponsesAdminData,
        submitResponse: async () => Promise.resolve(null),
    },
    parameters: {
        docs: {
            description: {
                story: 'Baseline rendering of grouped responses with no interaction.',
            },
        },
    },
};

// `vitest/browser`'s page.viewport() only resolves under the Vitest test
// runner (`npm run test:storybook`) — it's unavailable both when previewed
// interactively in the Storybook UI and, more importantly, in the static
// build Chromatic captures, where it crashes at module-load time before this
// story's own play function body ever runs. `disableSnapshot` keeps Chromatic
// from executing/snapshotting this story at all — it exists purely as a
// Vitest browser-mode test, not something Chromatic should ever attempt.
export const ResponsiveOverflow: Story = {
    ...Render,
    parameters: {
        ...Render.parameters,
        chromatic: { disableSnapshot: true },
        docs: {
            description: {
                story: 'Not a visual story — asserts this component never forces its own horizontal overflow across a range of widths, standing in for the effective-viewport shrink caused by browser zoom. Rendered standalone/fullscreen here, so it can\'t reproduce overflow caused by a narrower real-world container (e.g. a nav sidebar eating into the available width) — only overflow the component itself is responsible for.',
            },
        },
    },
    play: async ({ canvasElement, viewMode }) => {
        if (viewMode === 'docs') return;

        let page: typeof import('vitest/browser')['page'];
        try {
            ({ page } = await import('vitest/browser'));
        } catch {
            return;
        }

        const widths = [1600, 1200, 900, 600, 375];
        const doc = canvasElement.ownerDocument;

        try {
            for (const width of widths) {
                await page.viewport(width, 900);
                await expect(doc.documentElement.scrollWidth).toBeLessThanOrEqual(width);
            }
        } finally {
            await page.viewport(1280, 720);
        }
    },
};

