import { chromium } from 'playwright';

const urls = [
    'http://localhost:8734/iframe.html?id=admin-responsesform--render&viewMode=story',
    'http://localhost:8734/iframe.html?id=admin-responsesform--responsive-overflow&viewMode=story',
];

const browser = await chromium.launch();
for (const url of urls) {
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    const errors = [];
    page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`));
    page.on('console', (msg) => {
        if (msg.type() === 'error') errors.push(`console.error: ${msg.text()}`);
    });
    await page.goto(url, { waitUntil: 'networkidle' });
    try {
        await page.waitForSelector('text=Search players', { timeout: 15000 });
    } catch {
        errors.push('story never rendered (Search players not found)');
    }
    await page.waitForTimeout(2000);
    console.log(url);
    console.log('ERRORS:', JSON.stringify(errors, null, 2));
    await page.close();
}
await browser.close();
